import * as zlib from 'node:zlib';
function main(): void {
  const codes: any = (zlib as any).codes;
  console.log('codes', typeof codes, Object.keys(codes).length, Object.isFrozen(codes));
  console.log(Object.keys(codes).map((k: string): string => k + '=' + codes[k]).join(' '));
  console.log(codes.Z_OK, codes[0], codes[-6], codes.Z_VERSION_ERROR, codes[-3]);
}
